hunks.new:
The policy retries only `RetryError::Transient` failures. `RetryError::Permanent`
failures return immediately. `max_attempts` counts the initial call, so a value of
`1` disables retries. Delays start at `base_delay_ms`, double for each subsequent
retry, and saturate at `max_delay_ms` without arithmetic overflow.

Example configuration:

```rust
use jobrunner::{run_job, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
```

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig { max_attempts, base_delay_ms: 10, max_delay_ms: 25 }
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls < 3 { Err(RetryError::Transient("busy".into())) } else { Ok(()) }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_retry() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_budget_includes_first_call_and_delays_are_bounded() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still busy".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("still busy".into())));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }
}

