//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay before retry `retry_number`, where the first retry is 1.
    pub fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let exponent = retry_number.saturating_sub(1);
        let delay = if exponent >= u64::BITS {
            u64::MAX
        } else {
            self.base_delay_ms
                .checked_mul(1u64 << exponent)
                .unwrap_or(u64::MAX)
        };
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_growth_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX / 2 + 1,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(1), u64::MAX / 2 + 1);
        assert_eq!(config.delay_for_retry(2), u64::MAX);
        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }

    #[test]
    fn delay_is_capped_at_configured_maximum() {
        let config = RetryConfig {
            max_attempts: 4,
            base_delay_ms: 25,
            max_delay_ms: 60,
        };

        assert_eq!(config.delay_for_retry(1), 25);
        assert_eq!(config.delay_for_retry(2), 50);
        assert_eq!(config.delay_for_retry(3), 60);
    }
}

